// Merge: day N prayers replace DAILY_CONTENT[N-1]'s morning, night and devotion prayer
(function() {
  if (typeof DAILY_CONTENT === 'undefined') return;
  Object.keys(DAILY_PRAYERS).forEach(function(key) {
    const p = DAILY_PRAYERS[key];
    const target = DAILY_CONTENT[parseInt(key, 10) - 1];
    if (!target) return;
    if (p.morning) target.morning = Array.isArray(p.morning) ? p.morning.join('\n\n') : p.morning;
    if (p.night) target.night = Array.isArray(p.night) ? p.night.join('\n\n') : p.night;
    if (p.devotion && target.devotion) target.devotion.prayer = p.devotion;
  });
})();
